    "content": "import json
import sys


def main(argv):
    if len(argv) != 2:
        print("usage: failed_report.py RESULTS.jsonl", file=sys.stderr)
        return 2
    path = argv[1]
    failed = 0
    skipped = 0
    try:
        fh = open(path, "r", encoding="utf-8")
    except OSError as exc:
        print(f"ERROR: cannot read {path}: {exc}", file=sys.stderr)
        return 2
    with fh:
        for lineno, line in enumerate(fh, start=1):
            line = line.strip()
            if not line:
                continue
            try:
                row = json.loads(line)
            except json.JSONDecodeError as exc:
                skipped += 1
                print(f"SKIPPED {path}: line {lineno}: {exc.msg}")
                continue
            if row.get("status") == "failed":
                failed += 1
    print(failed)
    print(skipped)
    if skipped:
        print("LINE-REPORTS-INCOMPLETE")
        return 1
    print("LINE-REPORTS-COMPLETE")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
